public class MyClass {
    public void doSomethingElse(IProgressMonitor monitor) {
        SubMonitor subMonitor = SubMonitor.convert(monitor, 10);
        try {
            subMonitor.step(2); // Argument is not 1, should not match
            subMonitor.anotherMethod(1); // Different method, should not match
        } finally {
            subMonitor.done();
        }
    }
}
